    @EventHandler( payloadType=CreateActivityEvent.class )
    public void handle( CreateActivityEvent event) {
	    LOGGER.info("handling CreateActivityEvent - " + event );
	    Activity entity = new Activity();
            entity.setActivityId( event.getActivityId() );
            entity.setSubject( event.getSubject() );
            entity.setDueDate( event.getDueDate() );
            entity.setStartAt( event.getStartAt() );
            entity.setEndAt( event.getEndAt() );
            entity.setLocation( event.getLocation() );
            entity.setActivityType( event.getActivityType() );
            entity.setStatus( event.getStatus() );
            entity.setPriority( event.getPriority() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllActivity( entity );
    }

