    /**
     * Method to retrieve the Activity via an ActivityPrimaryKey.
     * @param 	id Long
     * @return 	Activity
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Activity handle( FindActivityQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getActivityId() );
    }
    
    /**
     * Method to retrieve a collection of all Activitys
     *
     * @param	query	FindAllActivityQuery 
     * @return 	List<Activity> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Activity> handle( FindAllActivityQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindActivity,
 * but only if the id matches
 *
 * @param		entity	Activity
 */
	protected void emitFindActivity( Activity entity ) {
		LOGGER.info("handling emitFindActivity" );
		
	    queryUpdateEmitter.emit(FindActivityQuery.class,
	                            query -> query.getFilter().getActivityId().equals(entity.getActivityId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllActivity
	 * 
	 * @param		entity	Activity
	 */
	protected void emitFindAllActivity( Activity entity ) {
		LOGGER.info("handling emitFindAllActivity" );
		
	    queryUpdateEmitter.emit(FindAllActivityQuery.class,
	                            query -> true,
	                            entity);
	}

